/** A beeswarm: points along a categorical axis, moved aside so none overlap. */
export interface SwarmProps extends Pick<MarkProps, "z" | "position" | "fill" | "color" | "size" | "width" | "opacity" | "outlineColor" | "outlineOpacity" | "outlineWidth" | "fillScale" | "colorScale" | "colormap" | "sizeScale" | "widthScale" | "outlineColorScale" | "opacityScale" | "label" | "legend" | "visible" | "domains" | "blend" | "glow" | "shade" | "options" | "name" | "identity" | "select" | "hover" | "tooltip" | "brush" | "nearby" | "nearest" | "respond" | "selectionOpacity" | "drag" | "onclick" | "ondblclick" | "oncontextmenu" | "onpointerenter" | "onpointerleave" | "onpointermove" | "onpointerdown" | "onpointerup" | "onpointercancel" | "onpointerover" | "onpointerout" | "onpointermissed" | "ondrag" | "ondragend" | "enterEffect" | "exitEffect" | "animation" | "animationDuration" | "animationEasing" | "rotation" | "shape" | "shapeScale" | "sizeUnits" | "maxInstances"> {
  [option: string]: any;
  /** The categories along x for a vertical swarm, or the values for a horizontal one. */
  x: string;
  /** The values for a vertical swarm, or the categories along y for a horizontal one. */
  y: string;
  /** A vertical swarm spreads its points sideways from categories on x; a horizontal one spreads them up and down from categories on y. */
  orientation?: "horizontal" | "vertical";
  /** The gap kept between neighboring points. */
  padding?: number;
  /** The seed of the random order the points are placed in: another seed arranges the same points differently. */
  seed?: number;
}

/** Violin plots: each group's distribution as a mirrored density curve. */
export interface ViolinProps extends Pick<MarkProps, "z" | "position" | "fill" | "color" | "size" | "opacity" | "outlineColor" | "outlineOpacity" | "outlineWidth" | "fillScale" | "colorScale" | "colormap" | "sizeScale" | "outlineColorScale" | "opacityScale" | "label" | "legend" | "visible" | "domains" | "blend" | "glow" | "shade" | "options" | "name" | "identity" | "select" | "hover" | "tooltip" | "nearest" | "respond" | "selectionOpacity" | "onclick" | "ondblclick" | "oncontextmenu" | "onpointerenter" | "onpointerleave" | "onpointermove" | "onpointerdown" | "onpointerup" | "onpointercancel" | "onpointerover" | "onpointerout" | "onpointermissed" | "enterEffect" | "exitEffect" | "animation" | "animationDuration" | "animationEasing" | "maxInstances"> {
  [option: string]: any;
  /** The groups along x, a violin each, or the measurements for horizontal violins. */
  x: Channel;
  /** The measurements for vertical violins, or the groups along y for horizontal ones. */
  y: Channel;
  /** Vertical violins stand on categories along x; horizontal violins sit on categories along y. */
  orientation?: "horizontal" | "vertical";
  /** How the violins' sizes compare: equally wide ("width"), equal in area ("area"), or with areas in proportion to their groups' rows ("count"). */
  scale?: "width" | "area" | "count";
  /** Draw the density on both sides of its category, or on one side only (a half violin). */
  side?: "both" | "left" | "right";
  /** The width of the Gaussian kernel; "auto" picks it by Scott's rule. */
  bandwidth?: "auto" | number;
  /** How many points along the measurement axis the density is evaluated at. */
  resolution?: number;
  /** The share of its category's band each violin may fill, 0 to 1; on a numeric axis, a width in data units. */
  bandFraction?: number;
  /** Violin.width is not a prop: bandFraction sets the violin's share of its band. */
  width?: never;
}
